package main

import (
	"fmt"
	"strings"

	"github.com/hdt3213/godis/redis/protocol"
)

func validateArity(arity int, cmdArgs [][]byte) bool {
	argNum := len(cmdArgs)
	if arity >= 0 {
		return argNum == arity
	}
	return argNum >= -arity
}

func main() {
	// Test cases for FLUSHDB command
	testCases := [][][]byte{
		{[]byte("flushdb")},                     // Should be valid
		{[]byte("flushdb"), []byte("ASYNC")},    // Should be valid
		{[]byte("flushdb"), []byte("async")},    // Should be valid (case insensitive)
		{[]byte("flushdb"), []byte("SYNC")},     // Should be valid (ignored parameter)
		{[]byte("flushdb"), []byte("a"), []byte("b")}, // Should be invalid (too many args)
	}

	for i, cmdLine := range testCases {
		cmdName := strings.ToLower(string(cmdLine[0]))
		if cmdName == "flushdb" {
			valid := validateArity(-1, cmdLine) && len(cmdLine) <= 2
			fmt.Printf("Test case %d: %v -> Valid: %t\n", i+1, cmdLine, valid)

			// Show what the error message would be
			if !valid {
				errReply := protocol.MakeArgNumErrReply(cmdName)
				fmt.Printf("  Error: %s\n", errReply.ToBytes())
			} else {
				fmt.Printf("  Would execute FLUSHDB")
				if len(cmdLine) > 1 {
					fmt.Printf(" with parameter: %s", string(cmdLine[1]))
				}
				fmt.Println()
			}
		}
	}
}
EOF
